using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;
namespace BrakeToy.Editor
{
    public static class PlaygroundSceneBuilder
    {
        public const string ScenePath="Assets/BrakeToy/Scenes/ToyRoomPlayground.unity",Root="Assets/BrakeToy/Art/Playground/";private static int part;
        [MenuItem("Tools/Brake Toy/Open Playground v0.8")]public static void Open(){if(!File.Exists(ScenePath))Create();else EditorSceneManager.OpenScene(ScenePath);}
        public static void Create()
        {
            if(File.Exists(ScenePath))throw new System.InvalidOperationException("Preserve existing Playground scene");foreach(string d in new[]{"Materials","Meshes","Vehicles"})Directory.CreateDirectory(Root+d);AssetDatabase.Refresh();
            var scene=EditorSceneManager.OpenScene(JoyfulSceneBuilder.ScenePath);EditorSceneManager.SaveScene(scene,ScenePath);var g=Object.FindFirstObjectByType<GameManager>();g.name="Brake Toy — Playground v0.8";g.gameObject.AddComponent<PlaygroundRun>();g.gameObject.AddComponent<PlaygroundUI>();var atmosphere=g.gameObject.AddComponent<PlaygroundAtmosphere>();var encounters=g.gameObject.AddComponent<PlaygroundEncounters>();
            var safe=Material("Safe",new Color(.09f,.68f,.35f),.3f);var risk=Material("Risk",new Color(1,.58f,.07f),.3f);encounters.SafeMaterial=safe;encounters.RiskMaterial=risk;var ink=Material("Rubber",new Color(.025f,.033f,.043f),.12f);var cream=Material("Book paper",new Color(.85f,.80f,.65f),.08f);var metal=Material("Brushed metal",new Color(.42f,.49f,.53f),.58f,.7f);
            var props=new GameObject("Pooled interactive gates and dominoes").transform;encounters.Props=new PlaygroundProp[8];for(int i=0;i<8;i++)
            {
                var root=new GameObject("Interactive prop "+i).transform;root.SetParent(props);var gate=new GameObject("Garage shutter").transform;gate.SetParent(root,false);LivingMeshFactory.Box("Gate leaf",gate,new Vector3(0,.9f,0),new Vector3(2.04f,1.8f,.20f),risk,.05f);for(int bar=0;bar<5;bar++)LivingMeshFactory.Box("Shutter rib",gate,new Vector3(0,.2f+bar*.33f,-.12f),new Vector3(1.9f,.025f,.025f),metal,.006f);
                var signal=GameObject.CreatePrimitive(PrimitiveType.Sphere);signal.name="Red amber green gate signal";Object.DestroyImmediate(signal.GetComponent<Collider>());signal.transform.SetParent(root,false);signal.transform.localPosition=new Vector3(0,2.1f,0);signal.transform.localScale=Vector3.one*.25f;signal.GetComponent<Renderer>().sharedMaterial=risk;
                var dominoes=new Transform[7];for(int n=0;n<7;n++){var t=new GameObject("Domino pivot "+n).transform;t.SetParent(root,false);t.localPosition=new Vector3(0,0,n*.62f);LivingMeshFactory.Box("Domino",t,new Vector3(0,.45f,0),new Vector3(.5f,.9f,.16f),n%2==0?cream:ink,.035f);for(int dot=0;dot<3;dot++)LivingMeshFactory.Sphere("Dot",t,new Vector3((dot%2==0?-.1f:.1f),.25f+dot*.2f,-.085f),Vector3.one*.055f,n%2==0?ink:cream);dominoes[n]=t;}
                encounters.Props[i]=new PlaygroundProp{Root=root,Gate=gate,Signal=signal.transform,Dominoes=dominoes};root.gameObject.SetActive(false);
            }
            encounters.RouteMarkers=new Transform[16];for(int i=0;i<16;i++){var t=new GameObject("Route choice arrow "+i).transform;t.SetParent(props);var mesh=new Mesh();mesh.vertices=new[]{new Vector3(-.15f,0,-1),new Vector3(.15f,0,-1),new Vector3(.15f,0,0),new Vector3(.45f,0,0),new Vector3(0,0,.65f),new Vector3(-.45f,0,0),new Vector3(-.15f,0,0)};mesh.triangles=new[]{0,2,1,0,6,2,6,4,2,6,5,4,2,4,3};mesh.RecalculateNormals();t.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=safe;t.gameObject.SetActive(false);encounters.RouteMarkers[i]=t;}
            atmosphere.Zones=new GameObject[3];Color[] colors={new Color(.16f,.49f,.68f),new Color(.95f,.52f,.12f),new Color(.77f,.12f,.25f)};for(int zone=0;zone<3;zone++){var t=new GameObject(new[]{"Toy town reversible dressing","Construction reversible dressing","Race corner reversible dressing"}[zone]).transform;atmosphere.Zones[zone]=t.gameObject;var mat=Material("Zone "+zone,colors[zone],.24f);for(int side=-1;side<=1;side+=2)for(int n=0;n<7;n++){float x=side*4.75f,z=n*6-5;if(zone==0){LivingMeshFactory.Box("Town house",t,new Vector3(x,.45f,z),new Vector3(.7f,.9f,.7f),mat,.06f);LivingMeshFactory.Box("Window",t,new Vector3(x-side*.36f,.48f,z),new Vector3(.015f,.32f,.35f),cream,.02f);}else if(zone==1){LivingMeshFactory.Box("Building blocks",t,new Vector3(x,.25f,z),new Vector3(.8f,.5f,.8f),mat,.04f);LivingMeshFactory.Box("Raised block",t,new Vector3(x,.65f,z),new Vector3(.6f,.3f,.6f),cream,.04f);}else{LivingMeshFactory.Box("Race chevron",t,new Vector3(x,.34f,z),new Vector3(.12f,.68f,.9f),n%2==0?mat:cream,.035f);}}}
            // Clone every scene material before tuning. Historical scenes and prefab assets stay intact.
            var map=new System.Collections.Generic.Dictionary<Material,Material>();foreach(var r in Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include,FindObjectsSortMode.None)){var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++){var old=mats[i];if(!old||AssetDatabase.GetAssetPath(old).StartsWith(Root))continue;if(!map.TryGetValue(old,out var m)){m=new Material(old);m.name="Playground "+old.name;string name=old.name.ToLowerInvariant();if(m.HasProperty("_Smoothness"))m.SetFloat("_Smoothness",name.Contains("fabric")||name.Contains("cotton")||name.Contains("paper")?.06f:name.Contains("ink")||name.Contains("tire")?.13f:name.Contains("metal")?.58f:.32f);if(m.HasProperty("_BaseColor")&&(name.Contains("cream")||name.Contains("white"))){var c=m.GetColor("_BaseColor");m.SetColor("_BaseColor",new Color(c.r*.90f,c.g*.90f,c.b*.90f,c.a));}AssetDatabase.CreateAsset(m,AssetDatabase.GenerateUniqueAssetPath(Root+"Materials/"+m.name+".mat"));map[old]=m;}mats[i]=m;}r.sharedMaterials=mats;}
            Vehicles(g,ink,cream,metal);PersistMeshes();g.Arcade.DistanceRecordKey="BrakeToy.v08.distance";g.Arcade.StyleRecordKey="BrakeToy.v08.style";PlayerSettings.bundleVersion="0.8.0";PlayerSettings.Android.bundleVersionCode=8;EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(ScenePath,true)}.Concat(EditorBuildSettings.scenes.Where(s=>s.path!=ScenePath)).ToArray();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Upgrade();Debug.Log("Playground scene generated; testing and real render acceptance pending.");
        }
        private static Material Material(string name,Color color,float smooth,float metallic=0){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="Playground "+name};m.SetColor("_BaseColor",color);m.SetFloat("_Smoothness",smooth);m.SetFloat("_Metallic",metallic);AssetDatabase.CreateAsset(m,Root+"Materials/"+name+".mat");return m;}
        private static void PersistMeshes(){foreach(var f in Object.FindObjectsByType<MeshFilter>(FindObjectsInactive.Include,FindObjectsSortMode.None))if(f.sharedMesh&&!EditorUtility.IsPersistent(f.sharedMesh))AssetDatabase.CreateAsset(f.sharedMesh,AssetDatabase.GenerateUniqueAssetPath(Root+"Meshes/Mesh_"+part+++".asset"));}
        private static void Vehicles(GameManager g,Material rubber,Material paper,Material metal)
        {
            var template=g.Review.Visuals[0];string[] shapes={"Klasik coupe","Yuvarlak mini","Uzun kaslı coupe","Açık tavanlı cruiser","Açık teker kart","İkiz roket gövdeli","Alçak elektrikli wedge","Kubbeli uzay aracı","Uzun kaputlu roadster","Yüksek burunlu prestij"};
            for(int i=1;i<10;i++)
            {
                var old=g.Review.Visuals[i];var t=new GameObject(g.Review.Vehicles[i].Title+" distinct silhouette").transform;t.SetParent(old.parent,false);var color=g.Review.Vehicles[i].TrailColor;var paint=Material("Car paint "+i,color,.55f,i==8?.55f:.12f);float width=i==4?.58f:i==1?.70f:.78f,length=i==1?1.00f:i==4?1.03f:1.28f;float bodyY=i==4?.23f:.28f;
                LivingMeshFactory.Box("Distinct body",t,new Vector3(0,bodyY,0),new Vector3(width,i==1?.34f:.20f,length),paint,i==1?.16f:.065f);
                if(i==1)LivingMeshFactory.Sphere("Bubble cabin",t,new Vector3(0,.49f,-.04f),new Vector3(.61f,.39f,.68f),paint);
                else if(i==4){LivingMeshFactory.Box("Kart seat",t,new Vector3(0,.39f,-.18f),new Vector3(.35f,.26f,.30f),rubber,.025f);LivingMeshFactory.Box("Front wing",t,new Vector3(0,.20f,.52f),new Vector3(.84f,.06f,.18f),paint,.02f);}
                else if(i==3||i==8){LivingMeshFactory.Box("Open cockpit",t,new Vector3(0,.39f,-.08f),new Vector3(.52f,.12f,.50f),rubber,.035f);LivingMeshFactory.Box("Windshield",t,new Vector3(0,.52f,.20f),new Vector3(.56f,.25f,.04f),metal,.02f);LivingMeshFactory.Box("Seats",t,new Vector3(0,.47f,-.27f),new Vector3(.45f,.22f,.14f),paper,.03f);}
                else if(i==7)LivingMeshFactory.Sphere("Space canopy",t,new Vector3(0,.43f,-.06f),new Vector3(.62f,.34f,.66f),metal);
                else{float h=i==9?.35f:i==6?.15f:.23f;LivingMeshFactory.Box("Cabin",t,new Vector3(0,.37f+h*.5f,-.12f),new Vector3(.57f,h,.54f),metal,.055f);LivingMeshFactory.Box("Roof",t,new Vector3(0,.38f+h,-.14f),new Vector3(.59f,.055f,.49f),paint,.025f);}
                if(i==2)LivingMeshFactory.Box("Muscle hood scoop",t,new Vector3(0,.46f,.39f),new Vector3(.28f,.14f,.25f),rubber,.025f);
                if(i==5)foreach(float sign in new[]{-1f,1f}){LivingMeshFactory.Sphere("Rocket pod",t,new Vector3(sign*.30f,.43f,-.16f),new Vector3(.20f,.22f,1.0f),paint);LivingMeshFactory.Box("Rocket nozzle",t,new Vector3(sign*.30f,.42f,-.62f),new Vector3(.16f,.16f,.10f),metal,.02f);}
                if(i==6||i==7||i==9){LivingMeshFactory.Box("Rear wing",t,new Vector3(0,.56f,-.53f),new Vector3(.82f,.045f,.18f),paint,.015f);foreach(float side in new[]{-1f,1f})LivingMeshFactory.Box("Rear wing support "+side,t,new Vector3(side*.26f,.46f,-.53f),new Vector3(.035f,.20f,.05f),metal,.008f);}
                LivingMeshFactory.Box("Grille",t,new Vector3(0,.28f,length*.5f+.01f),new Vector3(i==9?.48f:.30f,i==9?.20f:.065f,.025f),rubber,.01f);foreach(float side in new[]{-1f,1f})LivingMeshFactory.Sphere("Headlight",t,new Vector3(side*.22f,i==4?.27f:.34f,length*.5f-.005f),new Vector3(.13f,.08f,.025f),paper);
                foreach(Transform wheel in template)if(wheel.name.StartsWith("Wheel")){var w=Object.Instantiate(wheel,t);w.name=wheel.name;}
                PersistMeshes();var definition=Object.Instantiate(g.Review.Vehicles[i]);definition.Silhouette=shapes[i];definition.VisualPrefab=PrefabUtility.SaveAsPrefabAsset(t.gameObject,Root+"Vehicles/Car_"+i+".prefab");AssetDatabase.CreateAsset(definition,Root+"Vehicles/Car_"+i+".asset");g.Review.Vehicles[i]=definition;g.Review.Visuals[i]=t;t.gameObject.SetActive(false);Object.DestroyImmediate(old.gameObject);
            }
        }
        public static void Upgrade()
        {
            var scene=EditorSceneManager.OpenScene(ScenePath);var g=Object.FindFirstObjectByType<GameManager>();var run=g.GetComponent<PlaygroundRun>();part=1000;
            if(!run.PowerRig){var rig=new GameObject("Power attachments — no collision").transform;run.PowerRig=rig;var rocket=new GameObject("Rocket engines").transform;rocket.SetParent(rig,false);run.RocketRig=rocket;var jet=new GameObject("Jetpack").transform;jet.SetParent(rig,false);run.JetRig=jet;var metal=AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/Brushed metal.mat");var flame=Material("Power flame",new Color(.12f,.76f,1),.3f);flame.EnableKeyword("_EMISSION");flame.SetColor("_EmissionColor",new Color(.05f,.7f,2));foreach(float side in new[]{-1f,1f}){LivingMeshFactory.Sphere("Rocket canister",rocket,new Vector3(side*.25f,.50f,-.35f),new Vector3(.20f,.20f,.56f),metal);LivingMeshFactory.Sphere("Rocket exhaust",rocket,new Vector3(side*.25f,.5f,-.86f),new Vector3(.15f,.15f,.60f),flame);LivingMeshFactory.Box("Jet tank",jet,new Vector3(side*.22f,.62f,-.2f),new Vector3(.18f,.44f,.22f),metal,.04f);LivingMeshFactory.Sphere("Jet flame",jet,new Vector3(side*.22f,.15f,-.2f),new Vector3(.12f,.55f,.12f),flame);}rocket.gameObject.SetActive(false);jet.gameObject.SetActive(false);PersistMeshes();}
            if(g.Arcade.Challenges.RiskStars.Length<24){var stars=g.Arcade.Challenges.RiskStars.ToList();while(stars.Count<24){var star=Object.Instantiate(stars[0],stars[0].parent);star.name="Reusable risk star "+stars.Count;star.gameObject.SetActive(false);stars.Add(star);}g.Arcade.Challenges.RiskStars=stars.ToArray();}
            for(int i=1;i<g.Review.Visuals.Length;i++){var visual=g.Review.Visuals[i];if(visual.Find("Headlights seated"))continue;foreach(Transform t in visual)if(t.name=="Headlight"){var pos=t.localPosition;pos.x=Mathf.Sign(pos.x)*.22f;pos.y=i==4?.27f:.34f;pos.z=(i==1?1:i==4?1.03f:1.28f)*.5f-.005f;t.localPosition=pos;}new GameObject("Headlights seated").transform.SetParent(visual,false);PrefabUtility.SaveAsPrefabAsset(visual.gameObject,Root+"Vehicles/Car_"+i+".prefab");}
            foreach(int i in new[]{6,7,9}){var visual=g.Review.Visuals[i];if(visual.Find("Rear wing support -1"))continue;var supportMaterial=AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/Brushed metal.mat");foreach(float side in new[]{-1f,1f})LivingMeshFactory.Box("Rear wing support "+side,visual,new Vector3(side*.26f,.46f,-.53f),new Vector3(.035f,.20f,.05f),supportMaterial,.008f);PersistMeshes();PrefabUtility.SaveAsPrefabAsset(visual.gameObject,Root+"Vehicles/Car_"+i+".prefab");}
            EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();
        }
    }
}
